const bcrypt = require('bcrypt');

/**
 * Hash the given password securely and return the hash as a string.
 *
 * @param {string} password - The password to be hashed.
 * @returns {Promise<string>} The securely hashed password.
 */
async function get_password_hash(password) {
  // bcrypt automatically handles salting internally.
  // The saltRounds parameter controls the computational cost (work factor).
  // A value of 10 is generally recommended as a good balance between security and performance
  // for most applications as of current computing power. This value should be reviewed periodically
  // and potentially increased as computing power advances.
  const saltRounds = 10; 

  try {
    const hash = await bcrypt.hash(password, saltRounds);
    return hash;
  } catch (error) {
    // If hashing fails for any reason (e.g., invalid input, system error),
    // re-throw a more descriptive error to inform the caller.
    // The caller is responsible for handling this promise rejection.
    throw new Error(`Failed to hash password securely: ${error.message}`);
  }
}
